import java.util.Scanner;

public class FlightCargo {
    private String sender;
    private String destination;
    private double weightKg;
    private double charge;

    public FlightCargo() {
        sender = "";
        destination = "";
        weightKg = 0.0;
        charge = 0.0;
    }

    public void input() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Sender Name: ");
        sender = in.nextLine();
        System.out.print("Enter Destination City: ");
        destination = in.nextLine();
        System.out.print("Enter Consignment Weight (kg): ");
        weightKg = in.nextDouble();
    }

    public void compute() {
        double weightRate;
        if (weightKg <= 20.0) {
            weightRate = weightKg * 60.0;
        } else if (weightKg <= 50.0) {
            weightRate = (20.0 * 60.0) + (weightKg - 20.0) * 50.0;
        } else {
            weightRate = (20.0 * 60.0) + (30.0 * 50.0) + (weightKg - 50.0) * 40.0;
        }

        double subtotal = 500.0 + weightRate;
        double fuelSurcharge = 0.10 * subtotal;
        charge = subtotal + fuelSurcharge;
    }

    public void show() {
        System.out.println("\n============== AIR CARGO WAYBILL ==============");
        System.out.println("Sender Name      : " + sender);
        System.out.println("Destination City : " + destination);
        System.out.println("Weight (kg)      : " + weightKg + " kg");
        System.out.println("Total Charges    : Rs. " + charge);
        System.out.println("===============================================");
    }

    public static void main(String[] args) {
        FlightCargo fc = new FlightCargo();
        fc.input();
        fc.compute();
        fc.show();
    }
}
```

