        for (int i = 0; i < N; i++) {
            rotated[(i + k) % N] = arr[i];
        }

        System.out.print("\nOriginal Array: ");
        for (int v : arr) System.out.print(v + " ");
        System.out.println();

        System.out.print("Rotated Array : ");
        for (int v : rotated) System.out.print(v + " ");
        System.out.println();
    }
}
