import java.util.Scanner;

public class KaprekarNumberCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter positive integer: ");
        int p = sc.nextInt();

        long square = (long) p * p;

        // Count digits of p
        int temp = p;
        int d = 0;
        while (temp > 0) {
            d++;
            temp /= 10;
        }

        long divisor = (long) Math.pow(10, d);
        long rightPart = square % divisor;
        long leftPart = square / divisor;

        long sum = leftPart + rightPart;

        System.out.println("\nNumber = " + p + ", Square = " + square);
        System.out.println("Left Part = " + leftPart + ", Right Part = " + rightPart);
        System.out.println("Sum of Parts = " + sum);

        if (sum == p) {
            System.out.println(p + " is a KAPREKAR NUMBER.");
        } else {
            System.out.println(p + " is NOT a Kaprekar Number.");
        }
    }
}
```

