import java.util.Scanner;

public class MagicSquareCheck {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        final int N = 3;
        int[][] mat = new int[N][N];

        System.out.println("Enter 9 elements for 3x3 matrix:");
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) mat[i][j] = in.nextInt();
        }

        int targetSum = 0;
        for (int j = 0; j < N; j++) targetSum += mat[0][j]; // First row sum

        boolean isMagic = true;

        // Check rows
        for (int i = 1; i < N; i++) {
            int rSum = 0;
            for (int j = 0; j < N; j++) rSum += mat[i][j];
            if (rSum != targetSum) isMagic = false;
        }

        // Check cols
        for (int j = 0; j < N; j++) {
            int cSum = 0;
            for (int i = 0; i < N; i++) cSum += mat[i][j];
            if (cSum != targetSum) isMagic = false;
        }

        // Check diagonals
        int d1 = 0, d2 = 0;
        for (int i = 0; i < N; i++) {
            d1 += mat[i][i];
            d2 += mat[i][N - 1 - i];
        }
        if (d1 != targetSum || d2 != targetSum) isMagic = false;

        System.out.println("\nMatrix Representation:");
        for (int[] row : mat) {
            for (int v : row) System.out.printf("%4d", v);
            System.out.println();
        }

        if (isMagic) {
            System.out.println("\nThe matrix is a MAGIC SQUARE (Magic Constant = " + targetSum + ").");
        } else {
            System.out.println("\nThe matrix is NOT a Magic Square.");
        }
    }
}
```

