import java.util.Scanner;

public class MenuHcfLcmPattern {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("========== UTILITY MENU ==========");
        System.out.println("1. HCF and LCM Calculation");
        System.out.println("2. Number Triangle Pattern");
        System.out.print("Enter choice (1 or 2): ");
        int choice = sc.nextInt();

        switch (choice) {
            case 1:
                System.out.print("Enter first number a: ");
                int a = sc.nextInt();
                System.out.print("Enter second number b: ");
                int b = sc.nextInt();

                int x = a, y = b;
                while (y != 0) {
                    int r = x % y;
                    x = y;
                    y = r;
                }
                int hcf = x;
                long lcm = ((long) a * b) / hcf;

                System.out.println("HCF(" + a + ", " + b + ") = " + hcf);
                System.out.println("LCM(" + a + ", " + b + ") = " + lcm);
                break;

            case 2:
                System.out.print("Enter number of rows: ");
                int rows = sc.nextInt();
                int count = 1;
                System.out.println("\nPattern Output:");
                for (int i = 1; i <= rows; i++) {
                    for (int j = 1; j <= i; j++) {
                        System.out.printf("%4d", count++);
                    }
                    System.out.println();
                }
                break;

            default:
                System.out.println("Invalid Selection.");
        }
    }
}
```

